/* Chapter images — embedded PNG/JPG (generate: node scripts/gen_chapter_images.cjs) */
(function (w) {
  w.OCEAN_CHAPTER_IMAGES = {"midnight":{"main-1":"data:image/png;base64,","main-2":"data:image/png;base64,","main-3":"data:image/png;base64,","explain-1":"data:image/png;base64,","explain-2":"data:image/png;base64,","explain-3":"data:image/png;base64,"}};

  function imgTag(uri, alt) {
    return '<img class="chapter-hero-img" src="' + uri + '" alt="' + alt.replace(/"/g, "&quot;") + '" decoding="async">';
  }

  w.OceanChapterImage = {
    render: function (id, slot, title) {
      var ch = w.OCEAN_CHAPTER_IMAGES[id];
      if (ch && ch[slot]) return imgTag(ch[slot], title + " — " + slot);
      return null;
    },
    getUri: function (id, slot) {
      var ch = w.OCEAN_CHAPTER_IMAGES[id];
      return ch && ch[slot] ? ch[slot] : null;
    }
  };
})(window);
